-- Migration: Year 4 - Ethics, Law & Health Systems (PART 2: 51-100)
-- Date: 2026-05-16
-- Target: US MD / MBBS / USMLE Step 3 Level
-- Topic: Healthcare systems — Medicare Part C & D

BEGIN;

DO $$ 
DECLARE 
    v_topic_id UUID;
BEGIN
    -- Fetch the topic_id dynamically via slug
    SELECT id INTO v_topic_id FROM topics WHERE slug = 'ethics-healthcare-systems' LIMIT 1;

    IF v_topic_id IS NULL THEN
        RAISE EXCEPTION 'Topic with slug "ethics-healthcare-systems" not found.';
    END IF;

    -- SECTION: MEDICARE PART C (MEDICARE ADVANTAGE)
    INSERT INTO mcqs (topic_id, question, options, correct_index, explanation) VALUES
    (v_topic_id, 'Medicare Part C is more commonly known as which of the following?', '["Medigap", "Medicare Advantage", "The Federal Drug Program", "Senior Care"]', 1, 'Medicare Advantage (MA) plans are Part C of Medicare.'),
    (v_topic_id, 'Which of the following entities provides the actual insurance coverage in a Medicare Advantage (Part C) plan?', '["The federal government (CMS)", "Private insurance companies approved by Medicare", "Individual state governments", "The Social Security Administration"]', 1, 'MA plans are offered by private companies that contract with Medicare to provide Part A and Part B benefits.'),
    (v_topic_id, 'To be eligible to join a Medicare Advantage plan, an individual must be enrolled in:', '["Part A only", "Part B only", "Both Part A and Part B", "Medicaid"]', 2, 'To join a Part C plan, you must already be enrolled in both Medicare Part A and Part B.'),
    (v_topic_id, 'Which of the following is a key difference between "Original Medicare" and "Medicare Advantage"?', '["Original Medicare covers vision and dental", "Medicare Advantage plans MUST have an annual out-of-pocket maximum", "Only Original Medicare requires a Part B premium", "Medicare Advantage is free for everyone"]', 1, 'Unlike Original Medicare, all Medicare Advantage plans are required by law to have an annual maximum out-of-pocket (MOOP) limit.'),
    (v_topic_id, 'Most Medicare Advantage plans combine which of the following into a single plan?', '["Parts A and B only", "Parts A, B, and D", "Part B and Medigap", "Part A and Long-term care"]', 1, 'Most MA plans are "MA-PD" plans, which bundle hospital (A), medical (B), and prescription drug (D) coverage.'),
    (v_topic_id, 'A patient in a Medicare Advantage HMO (Health Maintenance Organization) plan typically needs which of the following to see a specialist?', '["Nothing", "A referral from their Primary Care Physician (PCP)", "Authorization from the CMS", "A written request to the state"]', 1, 'HMO plans usually require a referral from a PCP for specialty care.'),
    (v_topic_id, 'If a patient in a standard Medicare Advantage HMO goes to an out-of-network provider for a non-emergency, how is the bill typically handled?', '["The plan pays 80%", "The plan pays 50%", "The patient usually pays the full cost (100%)", "Medicare Part B pays the bill"]', 2, 'In an HMO, out-of-network care (except for emergencies/urgencies) is generally not covered, leaving the patient responsible for the full cost.'),
    (v_topic_id, 'In a Medicare Advantage PPO (Preferred Provider Organization) plan, the patient:', '["Cannot see out-of-network providers", "Can see out-of-network providers but usually pays higher coinsurance", "Needs a referral for all specialists", "Does not have to pay any premiums"]', 1, 'PPOs offer more flexibility than HMOs, allowing out-of-network care at a higher cost-share without a referral.'),
    (v_topic_id, 'Which type of Medicare Advantage plan is specifically designed for individuals who have both Medicare and Medicaid?', '["HMO", "PPO", "D-SNP (Dual Eligible Special Needs Plan)", "PFFS (Private Fee-for-Service)"]', 2, 'Special Needs Plans (SNPs) are tailored for specific groups, like those with dual eligibility (D-SNPs).'),
    (v_topic_id, 'What happens to a patient''s Medicare Part B monthly premium when they join a Medicare Advantage plan?', '["It is eliminated", "They must still pay it (to Medicare) in addition to any MA plan premium", "It is paid by the state", "It is doubled"]', 1, 'Joining an MA plan does not exempt you from the Part B premium; you must continue to pay it to maintain your Medicare eligibility.'),
    (v_topic_id, 'Can a Medicare Advantage plan charge different copayments than Original Medicare for the same service?', '["No, they must be identical", "Yes, but they cannot exceed Original Medicare for certain services like dialysis or chemotherapy", "Yes, they can charge whatever they want", "Only if the patient is under 70"]', 1, 'MA plans have flexibility in cost-sharing but are legally restricted from charging more than Original Medicare for specific high-cost services like chemo, dialysis, or SNF care.'),
    (v_topic_id, 'Which of the following "extra" benefits is commonly offered by Medicare Advantage plans but NOT covered by Original Medicare?', '["Inpatient hospital stays", "Flu shots", "Routine vision and dental care", "Emergency room visits"]', 2, 'MA plans often compete by offering vision, hearing, dental, and fitness benefits (e.g., SilverSneakers).'),
    (v_topic_id, 'What is the "Star Rating" system for Medicare Advantage plans?', '["A measure of how many doctors are in the network", "A quality rating from 1 to 5 stars based on performance and patient satisfaction", "A ranking of the plan''s premium cost", "The number of states the plan operates in"]', 1, 'CMS uses a 5-star rating system to help beneficiaries compare the quality and performance of MA plans.'),
    (v_topic_id, 'When can a beneficiary typically join or switch Medicare Advantage plans?', '["Any time of the year", "Only on their birthday", "During the Annual Enrollment Period (Oct 15 - Dec 7)", "Only when they get sick"]', 2, 'The Annual Enrollment Period (AEP) is the main time to make changes to Medicare Advantage or Part D coverage.'),
    (v_topic_id, 'A patient joins a Medicare Advantage plan in October but decides in January they don''t like it. Is there a period to switch back to Original Medicare?', '["No", "Yes, during the Medicare Advantage Open Enrollment Period (Jan 1 - March 31)", "Only if they have a doctor''s note", "Only if the plan goes bankrupt"]', 1, 'The MA OEP allows those already in an MA plan to switch to a different MA plan or return to Original Medicare.'),

    -- SECTION: MEDICARE PART D (PRESCRIPTION DRUG COVERAGE)
    (v_topic_id, 'Medicare Part D provides coverage for which of the following?', '["Inpatient hospital medications", "Outpatient prescription drugs", "Injectable drugs given in the doctor''s office", "Vitamins and minerals"]', 1, 'Part D covers outpatient prescription drugs. Drugs given during a hospital stay are Part A; office-injected drugs are often Part B.'),
    (v_topic_id, 'A "PDP" (Prescription Drug Plan) is which of the following?', '["A drug benefit bundled with a hospital", "A stand-alone drug plan that works with Original Medicare", "A government-run pharmacy", "A discount card for the uninsured"]', 1, 'PDPs are stand-alone plans for people who have Original Medicare and want drug coverage.'),
    (v_topic_id, 'Which of the following is true regarding Part D enrollment?', '["It is mandatory for all seniors", "If you delay enrollment without creditable coverage, you may pay a permanent late-enrollment penalty", "It is free for everyone over 65", "It only covers generic drugs"]', 1, 'To avoid the Part D penalty, you must have "creditable" coverage (like from an employer or the VA) or sign up when first eligible.'),
    (v_topic_id, 'What is a "Formulary" in a Medicare Part D plan?', '["The list of doctors in the network", "The list of prescription drugs covered by the plan", "The billing department", "A type of medication used for heart failure"]', 1, 'The formulary is the specific list of drugs the plan covers.'),
    (v_topic_id, 'Drug "Tiers" in a Part D plan refer to:', '["The age of the patient", "Levels of cost-sharing, where lower tiers usually have lower copays", "The size of the pharmacy network", "How often the drug must be taken"]', 1, 'Tiers (e.g., Tier 1 Generics vs. Tier 5 Specialty) determine the patient''s out-of-pocket cost for a drug.'),
    (v_topic_id, 'A "Formulary Exception" is requested when:', '["A patient wants a cheaper drug", "A physician believes a non-covered drug is medically necessary for the patient", "The pharmacy is closed", "The drug is out of stock"]', 1, 'A prescriber can request an exception to get coverage for a drug not on the plan''s formulary or to get a lower tier copay.'),
    (v_topic_id, 'What is "Step Therapy" in a Part D plan?', '["A program to help patients walk more", "Requiring a patient to try a lower-cost, effective drug before the plan will cover a more expensive drug", "Paying for drugs in monthly steps", "A type of physical therapy"]', 1, 'Step therapy is a utilization management tool to control costs by starting with the most cost-effective treatments.'),
    (v_topic_id, 'The "Initial Coverage Limit" is the point where:', '["The plan starts paying", "The patient enters the \"Donut Hole\" coverage gap", "The patient becomes eligible for Medicare", "The premium is paid"]', 1, 'After the patient and plan spend a certain amount ($5,030 in 2024) on drugs, the patient enters the coverage gap.'),
    (v_topic_id, 'In the "Donut Hole" (Coverage Gap) in 2024, what percentage of the cost of brand-name and generic drugs does the patient typically pay?', '["10%", "25%", "50%", "100%"]', 1, 'Since 2020, the "Donut Hole" has been technically closed; patients pay 25% of the cost for both brand and generic drugs in this phase.'),
    (v_topic_id, 'When a patient reaches the "Catastrophic Coverage" phase in 2024, what is their coinsurance responsibility for drugs for the remainder of the year?', '["5%", "25%", "0% (No cost-sharing)", "A fixed $10 copay"]', 2, 'Starting in 2024, the Inflation Reduction Act eliminated the 5% coinsurance in the catastrophic phase, meaning drugs are essentially free after reaching the out-of-pocket threshold.'),
    (v_topic_id, 'For the year 2025, the Inflation Reduction Act will implement which major change to Part D?', '["Eliminate all premiums", "Cap annual out-of-pocket drug costs at $2,000", "Require all drugs to be generic", "Stop covering cancer drugs"]', 1, 'Starting in 2025, there will be a hard cap of $2,000 on annual out-of-pocket spending for Part D drugs.'),
    (v_topic_id, 'What is "Creditable Coverage" in relation to Medicare Part D?', '["Coverage that is only for generic drugs", "Drug coverage (e.g., from an employer) that is at least as good as Medicare''s standard benefit", "A high-credit score for insurance", "Coverage provided by a charity"]', 1, 'Having creditable coverage allows a person to delay Part D enrollment without incurring a penalty.'),
    (v_topic_id, 'The "Late Enrollment Penalty" for Part D is calculated based on:', '["The patient''s income", "1% of the national base beneficiary premium for every month the patient went without creditable coverage", "A flat fee of $500", "The number of drugs the patient takes"]', 1, 'The penalty is 1% per month, added to the monthly premium permanently.'),
    (v_topic_id, 'What is the "Extra Help" program (Low-Income Subsidy)?', '["A program to help seniors with grocery bills", "A Medicare program to help people with limited income and resources pay for Part D premiums and drug costs", "A volunteer service for house cleaning", "A type of supplemental health insurance"]', 1, 'Extra Help significantly reduces or eliminates Part D costs for eligible low-income beneficiaries.'),
    (v_topic_id, 'Medicare Part D plans are allowed to change their formulary during the year, but they must usually provide how much notice to affected beneficiaries?', '["None", "30 days", "60 days", "Only at the end of the year"]', 1, 'Plans must generally provide 30 days'' notice before removing a drug or changing its tier.'),

    -- SECTION: MEDICARE CROSS-CUTTING TOPICS (C & D)
    (v_topic_id, 'Which of the following drugs is EXCLUDED by law from coverage under Medicare Part D?', '["Insulin", "Drugs for weight loss or cosmetic purposes", "Anti-seizure medications", "Antibiotics"]', 1, 'Weight loss, fertility, cosmetic, and over-the-counter (OTC) drugs are generally excluded from Part D coverage by statute.'),
    (v_topic_id, 'Medicare Part D "Tier 5" drugs are usually designated as:', '["Preferred Generics", "Specialty Drugs (highest cost)", "Non-preferred Brands", "Experimental drugs"]', 1, 'Tier 5 is for high-cost specialty medications, often requiring high coinsurance (up to 25-33%).'),
    (v_topic_id, 'A patient on Medicare Advantage wants to know if they have "Catastrophic Coverage" for their hospital stays. Does this concept apply to Part A?', '["Yes", "No, \"Catastrophic Coverage\" is a specific term for the final phase of Part D drug coverage", "Only if they have cancer", "Only if the stay is > 100 days"]', 1, 'Catastrophic coverage is a Part D term. Part A has benefit periods and lifetime reserve days, but not a "catastrophic" phase.'),
    (v_topic_id, 'What is the "MOOP" in a Medicare Advantage plan?', '["Medicare Only Office Patient", "Maximum Out-of-Pocket limit", "Monthly Operating Office Payment", "Minimum Optional Outpatient Plan"]', 1, 'MOOP is the most a member will pay for covered Part A and B services in a year.'),
    (v_topic_id, 'Which of the following is true about Medicare Advantage PFFS (Private Fee-for-Service) plans?', '["They are the same as HMOs", "The plan determines how much it will pay providers and how much the patient must pay", "They always require a referral", "They are run by the state"]', 1, 'In PFFS plans, the plan decides the payment rates, and you can see any provider who accepts the plan''s terms.'),
    (v_topic_id, 'If a Medicare Advantage plan goes bankrupt or leaves the market, what happens to the beneficiaries?', '["They lose all health insurance", "They are granted a Special Enrollment Period (SEP) to join another plan or return to Original Medicare", "They must wait until October to get insurance", "They are automatically enrolled in Medicaid"]', 1, 'Loss of coverage due to a plan leaving the area triggers an SEP.'),
    (v_topic_id, 'Which of the following is a "Dual Eligible" individual?', '["Someone with two Part D plans", "Someone who qualifies for both Medicare and Medicaid", "Someone with Medicare and private ESI", "Someone who is both 65 and disabled"]', 1, 'Dual eligibles are among the most complex and high-cost populations in the US healthcare system.'),
    (v_topic_id, 'The "Medicare Plan Finder" is a tool on Medicare.gov used to:', '["Find the nearest hospital", "Compare Medicare Advantage and Part D plans based on cost and coverage", "Locate a specific doctor''s home address", "Track a patient''s medical records"]', 1, 'The Plan Finder is the primary tool for beneficiaries to compare plans during enrollment periods.'),
    (v_topic_id, 'Can a Medicare Advantage plan charge a higher premium to a patient because they have a pre-existing condition like diabetes?', '["Yes", "No, they must accept all eligible applicants regardless of health status", "Only if the patient is over 80", "Only if the plan is an HMO"]', 1, 'MA plans must accept all Medicare-eligible individuals (except those with ESRD in the past, though this changed in 2021 allowing ESRD patients to join). They cannot charge higher premiums based on health status.'),
    (v_topic_id, 'What is the "Risk Adjustment" (Hierarchical Condition Category - HCC) system in Medicare Advantage?', '["A way to penalize sick patients", "A system where Medicare pays plans more for enrolling patients with higher medical complexity", "A way to measure hospital fire safety", "A method for adjusting premiums based on patient age only"]', 1, 'Risk adjustment ensures that plans are fairly compensated for taking on sicker, more expensive patients.'),
    (v_topic_id, 'Under the Inflation Reduction Act, the cost of a one-month supply of any Medicare-covered insulin is capped at:', '["$25", "$35", "$50", "$100"]', 1, 'Since 2023, insulin costs for Medicare beneficiaries are capped at $35 per month.'),
    (v_topic_id, 'Does Medicare Part D cover vaccines like Shingrix (Shingles) or Tdap?', '["No, those are Part B", "Yes, most vaccines are covered under Part D at $0 cost-sharing starting in 2023", "Only if the patient is over 75", "Only if given in a hospital"]', 1, 'The IRA mandated $0 cost-sharing for most adult vaccines covered under Part D.'),
    (v_topic_id, 'Which of the following is NOT an MA plan type?', '["HMO", "PPO", "PDP", "SNP"]', 2, 'PDP is a stand-alone drug plan, not a Medicare Advantage plan (though MA plans often include drug coverage).'),
    (v_topic_id, 'A "Benefit Highlight" of Medicare Advantage is "Care Coordination." What does this mean?', '["Paying for the patient''s car", "A service to help manage multiple chronic conditions and ensure different doctors work together", "Checking the patient''s credit", "None of the above"]', 1, 'Care coordination is a core feature of many MA plans, especially SNPs.'),
    (v_topic_id, 'What is "Utilization Management" in a Part D plan?', '["The number of patients in a plan", "Tools like prior authorization, quantity limits, and step therapy used to manage costs", "The process of billing the government", "The size of the drug bottles"]', 1, 'UM tools are used by plans to ensure clinical appropriateness and control drug spending.'),
    (v_topic_id, 'If a patient has "Medicaid" and "Medicare," who pays for their Part D premiums?', '["The patient", "The state Medicaid program", "The federal \"Extra Help\" program (automatically)", "The doctor"]', 2, 'Dual eligibles automatically qualify for the full Low-Income Subsidy (Extra Help).'),
    (v_topic_id, 'Medicare Part D plans often use "Preferred Pharmacies." What is the benefit to the patient of using one?', '["The drugs are fresher", "They often have lower copayments or coinsurance", "They are open 24 hours", "They provide free delivery"]', 1, 'Preferred pharmacies have contracted with the plan to offer lower cost-sharing to members.'),
    (v_topic_id, 'What is the "Network" of a Medicare Advantage plan?', '["The computers used by the plan", "The group of doctors, hospitals, and other providers that have agreed to provide care to plan members", "The list of drugs the plan covers", "The states where the plan is sold"]', 1, 'Network restrictions are a key characteristic of MA plans, especially HMOs.'),
    (v_topic_id, 'Can a patient with a Medicare Advantage plan use their "Red, White, and Blue" Original Medicare card at the doctor?', '["Yes, for everything", "No, they must use the membership card from their MA plan", "Only for emergencies", "Only if the MA plan card is lost"]', 1, 'When you join an MA plan, the private plan becomes your primary insurer, and you must use their card for all services.'),
    (v_topic_id, 'If a patient is in a Part D "Catastrophic" phase at the end of December, what happens on January 1st?', '["They stay in the catastrophic phase", "The costs reset, and they begin a new \"Initial Coverage\" phase", "They lose their insurance", "They get a refund for the previous year"]', 1, 'Medicare Part D phases reset every calendar year.')
;

END $$;
COMMIT;
